### Task 12.2: Update Bicep Infrastructure

**Files:**
- Modify: `infra/main.bicep`

**Step 1: Add orchestrator and processor job definitions**

Add to `infra/main.bicep`:

```bicep
// Orchestrator Job
resource orchestratorJob 'Microsoft.App/jobs@2023-05-01' = {
  name: 'orchestrator'
  location: location
  properties: {
    environmentId: containerAppEnvironment.id
    configuration: {
      triggerType: 'Schedule'
      scheduleTriggerConfig: {
        cronExpression: '0 */6 * * *'  // Every 6 hours
      }
      replicaTimeout: 1800  // 30 minutes
      replicaRetryLimit: 0
    }
    template: {
      containers: [
        {
          name: 'orchestrator'
          image: '${containerRegistry}/orchestrator:latest'
          resources: {
            cpu: json('0.5')
            memory: '1Gi'
          }
          env: commonEnvVars
        }
      ]
    }
  }
}

// GPU Transcriber Job
resource gpuTranscriberJob 'Microsoft.App/jobs@2023-05-01' = {
  name: 'gpu-transcriber'
  location: location
  properties: {
    environmentId: containerAppEnvironment.id
    configuration: {
      triggerType: 'Manual'
      replicaTimeout: 7200  // 120 minutes (backstop)
      replicaRetryLimit: 0
    }
    template: {
      containers: [
        {
          name: 'gpu-transcriber'
          image: '${containerRegistry}/gpu-transcriber:latest'
          resources: {
            cpu: json('4')
            memory: '8Gi'
            // gpu: { count: 1, sku: 'T4' }  // Enable when GPU available
          }
          env: commonEnvVars
        }
      ]
      scale: {
        minExecutions: 0
        maxExecutions: 1
      }
    }
  }
}

// CPU Processor Job
resource cpuProcessorJob 'Microsoft.App/jobs@2023-05-01' = {
  name: 'cpu-processor'
  location: location
  properties: {
    environmentId: containerAppEnvironment.id
    configuration: {
      triggerType: 'Manual'
      replicaTimeout: 1800  // 30 minutes
      replicaRetryLimit: 0
    }
    template: {
      containers: [
        {
          name: 'cpu-processor'
          image: '${containerRegistry}/cpu-processor:latest'
          resources: {
            cpu: json('0.5')
            memory: '512Mi'
          }
          env: commonEnvVars
        }
      ]
      scale: {
        minExecutions: 0
        maxExecutions: 3
      }
    }
  }
}
```

**Step 2: Commit**

```bash
git add infra/main.bicep
git commit -m "feat(infra): add orchestrator, GPU transcriber, and CPU processor jobs"
```

