// ============================================================================
// Container Apps - API Service
// ============================================================================
resource apiApp 'Microsoft.App/containerApps@2023-05-01' = {
  name: 'ca-api-${baseName}'
  location: location
  identity: {
    type: 'UserAssigned'
    userAssignedIdentities: {
      '${managedIdentity.id}': {}
    }
  }
  properties: {
    managedEnvironmentId: containerAppsEnv.id
    workloadProfileName: 'Consumption'
    configuration: {
      ingress: {
        external: true
        targetPort: 8000
        transport: 'http'
        corsPolicy: {
          allowedOrigins: json(corsOrigins)
          allowCredentials: true
          allowedMethods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS']
          allowedHeaders: ['*']
        }
        customDomains: empty(apiCustomDomain) ? [] : [
          {
            name: apiCustomDomain
            certificateId: apiManagedCertificate.id
            bindingType: 'SniEnabled'
          }
        ]
      }
      registries: [
        {
          server: containerRegistry.properties.loginServer
          username: containerRegistry.listCredentials().username
          passwordSecretRef: 'acr-password'
        }
      ]
      secrets: [
        {
          name: 'acr-password'
          value: containerRegistry.listCredentials().passwords[0].value
        }
        {
          name: 'db-connection-string'
          keyVaultUrl: secretDbConnection.properties.secretUri
          identity: managedIdentity.id
        }
        {
          name: 'blob-connection-string'
          keyVaultUrl: secretBlobConnection.properties.secretUri
          identity: managedIdentity.id
        }
        {
          name: 'acs-connection-string'
          keyVaultUrl: secretAcsConnection.properties.secretUri
          identity: managedIdentity.id
        }
        {
          name: 'admin-api-key'
          keyVaultUrl: secretAdminApiKey.properties.secretUri
          identity: managedIdentity.id
        }
      ]
    }
    template: {
      containers: [
        {
          name: 'api'
          image: apiImage
          resources: {
            cpu: json('0.5')
            memory: '1Gi'
          }
          env: [
            { name: 'DATABASE_URL', secretRef: 'db-connection-string' }
            { name: 'BLOB_CONNECTION_STRING', secretRef: 'blob-connection-string' }
            { name: 'ACS_CONNECTION_STRING', secretRef: 'acs-connection-string' }
            { name: 'ADMIN_API_KEY', secretRef: 'admin-api-key' }
            { name: 'AZURE_FOUNDRY_ENDPOINT', value: aiFoundryEndpoint }
            { name: 'ADMIN_EMAIL', value: adminEmail }
            { name: 'EMAIL_SENDER', value: emailSender }
            { name: 'FRONTEND_URL', value: frontendUrl }
            { name: 'ADMIN_DASHBOARD_URL', value: adminDashboardUrl }
            { name: 'CORS_ORIGINS', value: corsOrigins }
            { name: 'CURRENT_PROMPT_VERSION', value: 'v1' }
            // Container Apps SDK for triggering batch jobs from validation endpoint
            { name: 'AZURE_SUBSCRIPTION_ID', value: subscription().subscriptionId }
            { name: 'AZURE_RESOURCE_GROUP', value: resourceGroup().name }
            { name: 'AZURE_CLIENT_ID', value: managedIdentity.properties.clientId }
            { name: 'GPU_T4_JOB_NAME', value: 'job-proc-gpu-t4-${baseName}' }
            { name: 'GPU_A100_JOB_NAME', value: 'job-proc-gpu-a100-${baseName}' }
            { name: 'CPU_JOB_NAME', value: 'job-proc-cpu-${baseName}' }
          ]
          probes: [
            {
              type: 'Liveness'
              httpGet: {
                path: '/health'
                port: 8000
              }
              periodSeconds: 30
            }
            {
              type: 'Readiness'
              httpGet: {
                path: '/health/ready'
                port: 8000
              }
              periodSeconds: 10
            }
          ]
        }
      ]
      scale: {
        minReplicas: isEphemeral ? 0 : 1
        maxReplicas: 3
        rules: [
          {
            name: 'http-scaling'
            http: {
              metadata: {
                concurrentRequests: '100'
              }
            }
          }
        ]
      }
    }
  }
}

