  name: 'job-cpu-processor-${baseName}'
  location: location
  identity: {
    type: 'UserAssigned'
    userAssignedIdentities: {
      '${managedIdentity.id}': {}
    }
  }
  properties: {
    environmentId: containerAppsEnv.id
    workloadProfileName: 'Consumption'
    configuration: {
      triggerType: 'Manual'
      replicaTimeout: 1800 // 30 minutes
      replicaRetryLimit: 0
      registries: [
        {
          server: containerRegistry.properties.loginServer
          username: containerRegistry.listCredentials().username
          passwordSecretRef: 'acr-password'
        }
      ]
      secrets: processorSecrets
    }
    template: {
      containers: [
        {
          name: 'cpu-processor'
          image: '${containerRegistry.properties.loginServer}/podcast-summarizer/cpu-processor:${imageTag}'
          resources: {
            cpu: json('0.5')
            memory: '512Mi'
          }
          env: concat(processorEnvBase, [
            { name: 'PROCESSING_MODE', value: 'cpu' }
          ])
        }
      ]
      scale: {
        minExecutions: 0
        maxExecutions: 3
      }
    }
  }
}

// ============================================================================
// Outputs
// ============================================================================
output apiUrl string = 'https://${apiApp.properties.configuration.ingress.fqdn}'
output acrLoginServer string = containerRegistry.properties.loginServer
output acrName string = containerRegistry.name
output keyVaultName string = keyVault.name
output storageAccountName string = storageAccount.name
output sqlServerFqdn string = sqlServer.properties.fullyQualifiedDomainName
output managedIdentityClientId string = managedIdentity.properties.clientId

