toolUseResult.originalFile:
// Podcast Summarizer V2 - Azure Infrastructure
// Usage:
//   az deployment group create -g podcast-summarizer-prod -f infra/main.bicep -p infra/parameters.prod.json
//   az deployment group create -g podcast-summarizer-test-123 -f infra/main.bicep -p environmentName=test-123 isEphemeral=true

@description('Environment name (prod, test-123, etc.)')
param environmentName string

@description('Azure region for resources')
param location string = 'westus3'

@description('Is this an ephemeral test environment?')
param isEphemeral bool = false

// Container image tag (images stored in ACR created by this template)
@description('Container image tag (e.g., latest, v1.0.0, sha-abc123)')
param imageTag string = 'latest'

@description('Admin email for alerts')
param adminEmail string = 'admin@bhavanaai.com'

@description('Email sender address for outbound emails (magic links, summaries)')
param emailSender string

@description('Frontend URL for magic links and CORS')
param frontendUrl string = 'https://podcast.bhavanaai.com'

@description('Admin dashboard URL')
param adminDashboardUrl string = ''

@description('CORS allowed origins (JSON array)')
param corsOrigins string = '["https://podcast.bhavanaai.com","https://happy-meadow-08bda7d1e.1.azurestaticapps.net","http://localhost:3000","http://localhost:5174"]'

@description('Azure AI Foundry endpoint URL')
param aiFoundryEndpoint string = ''

@description('Custom domain for API (empty to skip custom domain setup)')
param apiCustomDomain string = ''

@secure()
@description('Admin API key for local scripts')
param adminApiKey string = ''

// Naming convention
var baseName = 'podsum-${environmentName}'
var uniqueSuffix = uniqueString(resourceGroup().id)
var shortSuffix = substring(uniqueSuffix, 0, 6) // Shorter suffix for storage (24 char limit)
var acrName = 'acr${replace(baseName, '-', '')}${shortSuffix}'

// Container image references (use ACR created by this template)
var apiImage = '${acrName}.azurecr.io/podcast-summarizer/api:${imageTag}'
var jobsImage = '${acrName}.azurecr.io/podcast-summarizer/jobs:${imageTag}'

// ============================================================================
// Azure Container Registry
// ============================================================================
resource containerRegistry 'Microsoft.ContainerRegistry/registries@2023-07-01' = {
  name: acrName
  location: location
  sku: {
    name: 'Basic'
  }
  properties: {
    adminUserEnabled: true
  }
}

// ============================================================================
// Key Vault
// ============================================================================
resource keyVault 'Microsoft.KeyVault/vaults@2023-07-01' = {
  name: 'kv-${baseName}-${shortSuffix}'
  location: location
  properties: {
    sku: {
      family: 'A'
      name: 'standard'
    }
    tenantId: subscription().tenantId
    enableRbacAuthorization: true
    enableSoftDelete: !isEphemeral
    softDeleteRetentionInDays: isEphemeral ? 7 : 90
  }
}

// ============================================================================
// Storage Account
// ============================================================================
resource storageAccount 'Microsoft.Storage/storageAccounts@2023-01-01' = {
  name: 'st${replace(baseName, '-', '')}${shortSuffix}'
  location: location
  sku: {
    name: 'Standard_LRS'
  }
  kind: 'StorageV2'
  properties: {
    minimumTlsVersion: 'TLS1_2'
    allowBlobPublicAccess: false
    supportsHttpsTrafficOnly: true
  }
}

resource blobServices 'Microsoft.Storage/storageAccounts/blobServices@2023-01-01' = {
  parent: storageAccount
  name: 'default'
}

resource transcriptsContainer 'Microsoft.Storage/storageAccounts/blobServices/containers@2023-01-01' = {
  parent: blobServices
  name: 'transcripts'
}

resource summariesContainer 'Microsoft.Storage/storageAccounts/blobServices/containers@2023-01-01' = {
  parent: blobServices
  name: 'summaries'
}

resource audioStagingContainer 'Microsoft.Storage/storageAccounts/blobServices/containers@2023-01-01' = {
  parent: blobServices
  name: 'audio-staging'
}

// Lifecycle policy for audio-staging (7 day cleanup)
resource lifecyclePolicy 'Microsoft.Storage/storageAccounts/managementPolicies@2023-01-01' = {
  parent: storageAccount
  name: 'default'
  properties: {
    policy: {
      rules: [
        {
          name: 'cleanup-audio-staging'
          enabled: true
          type: 'Lifecycle'
          definition: {
            filters: {
              blobTypes: ['blockBlob']
              prefixMatch: ['audio-staging/']
            }
            actions: {
              baseBlob: {
                delete: {
                  daysAfterModificationGreaterThan: 30
                }
              }
            }
          }
        }
      ]
    }
  }
}

// ============================================================================
// Azure SQL Database (Standard DTU-based)
// ============================================================================
resource sqlServer 'Microsoft.Sql/servers@2023-05-01-preview' = {
  name: 'sql-${baseName}-${uniqueSuffix}'
  location: location
  properties: {
    administratorLogin: 'sqladmin'
    administratorLoginPassword: 'P@ssw0rd${uniqueSuffix}!' // In prod, use Key Vault
    minimalTlsVersion: '1.2'
  }
}

resource sqlDatabase 'Microsoft.Sql/servers/databases@2023-05-01-preview' = {
  parent: sqlServer
  name: 'podsum'
  location: location
  sku: {
    name: 'S0' // Standard tier, 10 DTUs
    tier: 'Standard'
  }
  properties: {
    collation: 'SQL_Latin1_General_CP1_CI_AS'
    maxSizeBytes: 107374182400 // 100 GB
    requestedBackupStorageRedundancy: 'Local' // Locally redundant storage
  }
}

// Allow Azure services to access SQL
resource sqlFirewallAzure 'Microsoft.Sql/servers/firewallRules@2023-05-01-preview' = {
  parent: sqlServer
  name: 'AllowAzureServices'
  properties: {
    startIpAddress: '0.0.0.0'
    endIpAddress: '0.0.0.0'
  }
}

// ============================================================================
// Azure Communication Services (Email)
// ============================================================================
// Email service and Azure-managed domain are created manually (portal provisioning required)
// We reference them as existing resources to link them to the communication service
resource emailService 'Microsoft.Communication/emailServices@2023-04-01' existing = {
  name: 'email-${baseName}'
}

resource emailDomain 'Microsoft.Communication/emailServices/domains@2023-04-01' existing = {
  parent: emailService
  name: 'AzureManagedDomain'
}

resource communicationService 'Microsoft.Communication/communicationServices@2023-04-01' = {
  name: 'acs-${baseName}'
  location: 'global'
  properties: {
    dataLocation: 'UnitedStates'
    linkedDomains: [
      emailDomain.id
    ]
  }
}

// ============================================================================
// Container Apps Environment
// ============================================================================
resource logAnalytics 'Microsoft.OperationalInsights/workspaces@2022-10-01' = {
  name: 'log-${baseName}'
  location: location
  properties: {
    sku: {
      name: 'PerGB2018'
    }
    retentionInDays: isEphemeral ? 30 : 90
  }
}

resource containerAppsEnv 'Microsoft.App/managedEnvironments@2023-05-01' = {
  name: 'cae-${baseName}'
  location: location
  properties: {
    appLogsConfiguration: {
      destination: 'log-analytics'
      logAnalyticsConfiguration: {
        customerId: logAnalytics.properties.customerId
        sharedKey: logAnalytics.listKeys().primarySharedKey
      }
    }
    workloadProfiles: [
      {
        name: 'Consumption'
        workloadProfileType: 'Consumption'
      }
      // GPU profiles for Whisper transcription (see design decisions doc)
      // Consumption-based GPUs: pay-per-use, scale to zero
      {
        name: 'gpu-t4'
        workloadProfileType: 'Consumption-GPU-NC8as-T4'
      }
      {
        name: 'gpu-a100'
        workloadProfileType: 'Consumption-GPU-NC24-A100'
      }
    ]
  }
}

// ============================================================================
// Managed Certificate for API Custom Domain
// Note: Certificate was created via CLI (managed certificates require async DNS validation)
// We reference it as 'existing' to use it in the Container App ingress configuration
// ============================================================================
resource apiManagedCertificate 'Microsoft.App/managedEnvironments/managedCertificates@2023-05-01' existing = if (!empty(apiCustomDomain)) {
  parent: containerAppsEnv
  name: 'mc-cae-podsum-pro-api-podcast-bhav-8815'
}

// ============================================================================
// Managed Identity
// ============================================================================
resource managedIdentity 'Microsoft.ManagedIdentity/userAssignedIdentities@2023-01-31' = {
  name: 'id-${baseName}'
  location: location
}

// Key Vault access for managed identity
resource keyVaultSecretsUser 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  name: guid(keyVault.id, managedIdentity.id, 'KeyVaultSecretsUser')
  scope: keyVault
  properties: {
    roleDefinitionId: subscriptionResourceId('Microsoft.Authorization/roleDefinitions', '4633458b-17de-408a-b874-0445c86b69e6') // Key Vault Secrets User
    principalId: managedIdentity.properties.principalId
    principalType: 'ServicePrincipal'
  }
}

// Storage Blob Data Contributor for managed identity
resource storageBlobContributor 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  name: guid(storageAccount.id, managedIdentity.id, 'StorageBlobDataContributor')
  scope: storageAccount
  properties: {
    roleDefinitionId: subscriptionResourceId('Microsoft.Authorization/roleDefinitions', 'ba92f5b4-2d11-453d-a403-e96b0029c9fe') // Storage Blob Data Contributor
    principalId: managedIdentity.properties.principalId
    principalType: 'ServicePrincipal'
  }
}

// Contributor role for managed identity to start Container Apps jobs
resource controllerJobRoleAssignment 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  name: guid(resourceGroup().id, managedIdentity.id, 'contributor-for-jobs')
  properties: {
    roleDefinitionId: subscriptionResourceId('Microsoft.Authorization/roleDefinitions', 'b24988ac-6180-42a0-ab88-20f7382dd24c') // Contributor
    principalId: managedIdentity.properties.principalId
    principalType: 'ServicePrincipal'
  }
}

// ============================================================================
// Secrets in Key Vault
// ============================================================================
resource secretDbConnection 'Microsoft.KeyVault/vaults/secrets@2023-07-01' = {
  parent: keyVault
  name: 'db-connection-string'
  properties: {
    // SQLAlchemy URL format for pyodbc - password is URL-encoded (@ -> %40, ! -> %21)
    value: 'mssql+pyodbc://sqladmin:P%40ssw0rd${uniqueSuffix}%21@${sqlServer.properties.fullyQualifiedDomainName}/podsum?driver=ODBC+Driver+18+for+SQL+Server&Encrypt=yes&TrustServerCertificate=no'
  }
}

resource secretBlobConnection 'Microsoft.KeyVault/vaults/secrets@2023-07-01' = {
  parent: keyVault
  name: 'blob-connection-string'
  properties: {
    value: 'DefaultEndpointsProtocol=https;AccountName=${storageAccount.name};AccountKey=${storageAccount.listKeys().keys[0].value};EndpointSuffix=core.windows.net'
  }
}

resource secretAcsConnection 'Microsoft.KeyVault/vaults/secrets@2023-07-01' = {
  parent: keyVault
  name: 'acs-connection-string'
  properties: {
    value: communicationService.listKeys().primaryConnectionString
  }
}

// Reference to manually-created youtube cookies secret
resource secretYoutubeCookies 'Microsoft.KeyVault/vaults/secrets@2023-07-01' existing = {
  parent: keyVault
  name: 'youtube-cookies'
}

resource secretAdminApiKey 'Microsoft.KeyVault/vaults/secrets@2023-07-01' = if (!empty(adminApiKey)) {
  parent: keyVault
  name: 'admin-api-key'
  properties: {
    value: adminApiKey
  }
}

// ============================================================================
// Container Apps - API Service
// ============================================================================
resource apiApp 'Microsoft.App/containerApps@2023-05-01' = {
  name: 'ca-api-${baseName}'
  location: location
  identity: {
    type: 'UserAssigned'
    userAssignedIdentities: {
      '${managedIdentity.id}': {}
    }
  }
  properties: {
    managedEnvironmentId: containerAppsEnv.id
    workloadProfileName: 'Consumption'
    configuration: {
      ingress: {
        external: true
        targetPort: 8000
        transport: 'http'
        corsPolicy: {
          allowedOrigins: json(corsOrigins)
          allowCredentials: true
          allowedMethods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS']
          allowedHeaders: ['*']
        }
        customDomains: empty(apiCustomDomain) ? [] : [
          {
            name: apiCustomDomain
            certificateId: apiManagedCertificate.id
            bindingType: 'SniEnabled'
          }
        ]
      }
      registries: [
        {
          server: containerRegistry.properties.loginServer
          username: containerRegistry.listCredentials().username
          passwordSecretRef: 'acr-password'
        }
      ]
      secrets: [
        {
          name: 'acr-password'
          value: containerRegistry.listCredentials().passwords[0].value
        }
        {
          name: 'db-connection-string'
          keyVaultUrl: secretDbConnection.properties.secretUri
          identity: managedIdentity.id
        }
        {
          name: 'blob-connection-string'
          keyVaultUrl: secretBlobConnection.properties.secretUri
          identity: managedIdentity.id
        }
        {
          name: 'acs-connection-string'
          keyVaultUrl: secretAcsConnection.properties.secretUri
          identity: managedIdentity.id
        }
        {
          name: 'admin-api-key'
          keyVaultUrl: secretAdminApiKey.properties.secretUri
          identity: managedIdentity.id
        }
      ]
    }
    template: {
      containers: [
        {
          name: 'api'
          image: apiImage
          resources: {
            cpu: json('0.5')
            memory: '1Gi'
          }
          env: [
            { name: 'DATABASE_URL', secretRef: 'db-connection-string' }
            { name: 'BLOB_CONNECTION_STRING', secretRef: 'blob-connection-string' }
            { name: 'ACS_CONNECTION_STRING', secretRef: 'acs-connection-string' }
            { name: 'ADMIN_API_KEY', secretRef: 'admin-api-key' }
            { name: 'AZURE_FOUNDRY_ENDPOINT', value: aiFoundryEndpoint }
            { name: 'ADMIN_EMAIL', value: adminEmail }
            { name: 'EMAIL_SENDER', value: emailSender }
            { name: 'FRONTEND_URL', value: frontendUrl }
            { name: 'ADMIN_DASHBOARD_URL', value: adminDashboardUrl }
            { name: 'CORS_ORIGINS', value: corsOrigins }
            { name: 'CURRENT_PROMPT_VERSION', value: 'v1' }
            // Container Apps SDK for triggering batch jobs from validation endpoint
            { name: 'AZURE_SUBSCRIPTION_ID', value: subscription().subscriptionId }
            { name: 'AZURE_RESOURCE_GROUP', value: resourceGroup().name }
            { name: 'AZURE_CLIENT_ID', value: managedIdentity.properties.clientId }
            { name: 'GPU_T4_JOB_NAME', value: 'job-proc-gpu-t4-${baseName}' }
            { name: 'GPU_A100_JOB_NAME', value: 'job-proc-gpu-a100-${baseName}' }
            { name: 'CPU_JOB_NAME', value: 'job-proc-cpu-${baseName}' }
          ]
          probes: [
            {
              type: 'Liveness'
              httpGet: {
                path: '/health'
                port: 8000
              }
              periodSeconds: 30
            }
            {
              type: 'Readiness'
              httpGet: {
                path: '/health/ready'
                port: 8000
              }
              periodSeconds: 10
            }
          ]
        }
      ]
      scale: {
        minReplicas: isEphemeral ? 0 : 1
        maxReplicas: 3
        rules: [
          {
            name: 'http-scaling'
            http: {
              metadata: {
                concurrentRequests: '100'
              }
            }
          }
        ]
      }
    }
  }
}

// ============================================================================
// Container Apps Jobs
// ============================================================================
resource discoveryJob 'Microsoft.App/jobs@2023-05-01' = {
  name: 'job-discovery-${baseName}'
  location: location
  identity: {
    type: 'UserAssigned'
    userAssignedIdentities: {
      '${managedIdentity.id}': {}
    }
  }
  properties: {
    environmentId: containerAppsEnv.id
    workloadProfileName: 'Consumption'
    configuration: {
      triggerType: 'Schedule'
      scheduleTriggerConfig: {
        cronExpression: '0 */12 * * *' // Every 12 hours
      }
      replicaTimeout: 1800 // 30 minutes
      replicaRetryLimit: 1
      registries: [
        {
          server: containerRegistry.properties.loginServer
          username: containerRegistry.listCredentials().username
          passwordSecretRef: 'acr-password'
        }
      ]
      secrets: [
        {
          name: 'acr-password'
          value: containerRegistry.listCredentials().passwords[0].value
        }
        {
          name: 'db-connection-string'
          keyVaultUrl: secretDbConnection.properties.secretUri
          identity: managedIdentity.id
        }
        {
          name: 'blob-connection-string'
          keyVaultUrl: secretBlobConnection.properties.secretUri
          identity: managedIdentity.id
        }
      ]
    }
    template: {
      containers: [
        {
          name: 'poller'
          image: jobsImage
          command: ['python', '-m', 'src.jobs.poller']
          resources: {
            cpu: json('0.5')
            memory: '1Gi'
          }
          env: [
            { name: 'DATABASE_URL', secretRef: 'db-connection-string' }
            { name: 'BLOB_CONNECTION_STRING', secretRef: 'blob-connection-string' }
          ]
        }
      ]
    }
  }
}

resource controllerJob 'Microsoft.App/jobs@2023-05-01' = {
  name: 'job-controller-${baseName}'
  location: location
  identity: {
    type: 'UserAssigned'
    userAssignedIdentities: {
      '${managedIdentity.id}': {}
    }
  }
  properties: {
    environmentId: containerAppsEnv.id
    workloadProfileName: 'Consumption'
    configuration: {
      triggerType: 'Schedule'
      scheduleTriggerConfig: {
        cronExpression: '0 */6 * * *' // Every 6 hours
      }
      replicaTimeout: 300 // 5 minutes
      replicaRetryLimit: 1
      registries: [
        {
          server: containerRegistry.properties.loginServer
          username: containerRegistry.listCredentials().username
          passwordSecretRef: 'acr-password'
        }
      ]
      secrets: [
        {
          name: 'acr-password'
          value: containerRegistry.listCredentials().passwords[0].value
        }
        {
          name: 'db-connection-string'
          keyVaultUrl: secretDbConnection.properties.secretUri
          identity: managedIdentity.id
        }
        {
          name: 'acs-connection-string'
          keyVaultUrl: secretAcsConnection.properties.secretUri
          identity: managedIdentity.id
        }
      ]
    }
    template: {
      containers: [
        {
          name: 'controller'
          image: jobsImage
          command: ['python', '-m', 'src.jobs.controller']
          resources: {
            cpu: json('0.25')
            memory: '0.5Gi'
          }
          env: [
            { name: 'DATABASE_URL', secretRef: 'db-connection-string' }
            { name: 'ACS_CONNECTION_STRING', secretRef: 'acs-connection-string' }
            { name: 'GPU_T4_JOB_NAME', value: 'job-proc-gpu-t4-${baseName}' }
            { name: 'GPU_A100_JOB_NAME', value: 'job-proc-gpu-a100-${baseName}' }
            { name: 'CPU_JOB_NAME', value: 'job-proc-cpu-${baseName}' }
            { name: 'AZURE_SUBSCRIPTION_ID', value: subscription().subscriptionId }
