import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { adminApi } from "@/lib/api";
import { useState } from "react";
import { Trash2, RefreshCw, CheckCircle2, XCircle } from "lucide-react";

export function AdminEpisodes() {
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);

  const { data, isLoading, refetch } = useQuery({
    queryKey: ["admin-episodes", page, search],
    queryFn: () =>
      adminApi.getEpisodes({
        page,
        search: search || undefined,
      }),
  });

  const handleDelete = async (episodeId: string) => {
    if (confirm("Are you sure you want to delete this episode?")) {
      await adminApi.deleteEpisode(episodeId);
      refetch();
    }
  };

  const handleReprocess = async (episodeId: string) => {
    const reprocessTranscript = confirm("Reprocess transcript?");
    const reprocessSummary = confirm("Reprocess summary?");
    if (reprocessTranscript || reprocessSummary) {
      await adminApi.reprocessEpisode(episodeId, {
        reprocess_transcript: reprocessTranscript,
        reprocess_summary: reprocessSummary,
      });
      refetch();
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">Episodes</h2>
        <Input
          placeholder="Search by title..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="max-w-xs"
        />
      </div>

      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Title</TableHead>
                <TableHead>Channel</TableHead>
                <TableHead>Source</TableHead>
                <TableHead>Published</TableHead>
                <TableHead>Transcript</TableHead>
                <TableHead>Summary</TableHead>
                <TableHead></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell
                    colSpan={7}
                    className="text-center py-8 text-muted-foreground"
                  >
                    Loading...
                  </TableCell>
                </TableRow>
              ) : data?.items.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={7}
                    className="text-center py-8 text-muted-foreground"
                  >
                    No episodes found
                  </TableCell>
                </TableRow>
              ) : (
                data?.items.map((episode) => (
                  <TableRow key={episode.episode_id}>
                    <TableCell className="max-w-xs truncate font-medium">
                      {episode.title || "Untitled"}
                    </TableCell>
                    <TableCell>{episode.channel_name}</TableCell>
                    <TableCell>
                      <Badge variant="outline">{episode.source_type}</Badge>
                    </TableCell>
                    <TableCell>
                      {episode.published_at
                        ? new Date(episode.published_at).toLocaleDateString()
                        : "-"}
                    </TableCell>
                    <TableCell>
                      {episode.has_transcript ? (
                        <CheckCircle2 className="h-4 w-4 text-green-500" />
                      ) : (
                        <XCircle className="h-4 w-4 text-muted-foreground" />
                      )}
                    </TableCell>
                    <TableCell>
                      {episode.has_summary ? (
                        <CheckCircle2 className="h-4 w-4 text-green-500" />
                      ) : (
                        <XCircle className="h-4 w-4 text-muted-foreground" />
                      )}
                    </TableCell>
                    <TableCell>
                      <div className="flex gap-1">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleReprocess(episode.episode_id)}
                          title="Reprocess"
                        >
                          <RefreshCw className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(episode.episode_id)}
                          title="Delete"
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {data && data.pages > 1 && (
        <div className="flex justify-center gap-2">
          <Button
            variant="outline"
            disabled={page === 1}
            onClick={() => setPage((p) => p - 1)}
          >
            Previous
          </Button>
          <span className="py-2">
            Page {page} of {data.pages}
          </span>
          <Button
            variant="outline"
            disabled={page >= data.pages}
            onClick={() => setPage((p) => p + 1)}
          >
            Next
          </Button>
        </div>
      )}
    </div>
  );
}

