import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { adminApi } from "@/lib/api";
import { useState, useEffect, useRef, Fragment, useCallback, useMemo } from "react";
import { Trash2, Power, PowerOff, Pencil, Play, Loader2, CheckCircle2, XCircle, Clock } from "lucide-react";
import { toast } from "sonner";
import { useValidationPolling, isTerminalStatus } from "@/hooks/useValidationPolling";
import { ValidationProgress } from "@/components/admin/ValidationProgress";
import type { AdminChannelDetail, AdminChannelSummary, ChannelStatus } from "@/lib/types";

const VALIDATION_STORAGE_KEY = "admin-validation-state";

interface ValidationState {
  channelId: string;
  jobId: string;
}

function saveValidationState(state: ValidationState | null) {
  if (state) {
    localStorage.setItem(VALIDATION_STORAGE_KEY, JSON.stringify(state));
  } else {
    localStorage.removeItem(VALIDATION_STORAGE_KEY);
  }
}

function loadValidationState(): ValidationState | null {
  try {
    const stored = localStorage.getItem(VALIDATION_STORAGE_KEY);
    return stored ? JSON.parse(stored) : null;
  } catch {
    return null;
  }
}

export function AdminChannels() {
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [typeFilter, setTypeFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState<ChannelStatus | "">("");
  const [editingChannel, setEditingChannel] = useState<AdminChannelDetail | null>(null);

  // Validation state - restore from localStorage on mount
  const [validatingChannelId, setValidatingChannelId] = useState<string | null>(() => {
    return loadValidationState()?.channelId ?? null;
  });
  const [activeJobId, setActiveJobId] = useState<string | null>(() => {
    return loadValidationState()?.jobId ?? null;
  });
  const handledJobIdRef = useRef<string | null>(null);

  // Helper to update both state and localStorage
  const setValidationState = useCallback((channelId: string | null, jobId: string | null) => {
    setValidatingChannelId(channelId);
    setActiveJobId(jobId);
    saveValidationState(channelId && jobId ? { channelId, jobId } : null);
  }, []);
  const [editForm, setEditForm] = useState({
    name: "",
    description: "",
    category: "",
    image_url: "",
    listen_url: "",
  });

  const queryClient = useQueryClient();

  const { data: jobStatus } = useValidationPolling(activeJobId);

  const { data, isLoading, refetch } = useQuery({
    queryKey: ["admin-channels", page, search, typeFilter, statusFilter],
    queryFn: () =>
      adminApi.getChannels({
        page,
        search: search || undefined,
        type: typeFilter || undefined,
        status: statusFilter || undefined,
      }),
  });

  // Check if any channel has a running validation (for auto-polling)
  const hasRunningValidation = useMemo(() => {
    return data?.items.some(
      (ch: AdminChannelSummary) =>
        ch.last_validation_status === "running" ||
        ch.last_validation_status === "pending"
    ) ?? false;
  }, [data?.items]);

  // Auto-poll when there are running validations (1 min - user can refresh manually)
  useEffect(() => {
    if (!hasRunningValidation) return;

    const interval = setInterval(() => {
      refetch();
    }, 60000); // Poll every 60 seconds

    return () => clearInterval(interval);
  }, [hasRunningValidation, refetch]);

  // Handle job completion - use ref to prevent duplicate handling
  useEffect(() => {
    if (!activeJobId || !isTerminalStatus(jobStatus?.status)) return;
    if (handledJobIdRef.current === activeJobId) return;

    // Mark as handled immediately to prevent duplicates
    handledJobIdRef.current = activeJobId;

    if (jobStatus?.status === "completed") {
      toast.success("Validation completed successfully");
      refetch();
    } else {
      toast.error(`Validation ${jobStatus?.status}: ${jobStatus?.error || "Unknown error"}`);
    }

    // Clear state asynchronously to satisfy ESLint rule
    queueMicrotask(() => {
      setValidationState(null, null);
    });
  }, [activeJobId, jobStatus?.status, jobStatus?.error, refetch, setValidationState]);

  const updateMutation = useMutation({
    mutationFn: (data: { channelId: string; updates: Parameters<typeof adminApi.updateChannel>[1] }) =>
      adminApi.updateChannel(data.channelId, data.updates),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-channels"] });
      setEditingChannel(null);
    },
  });

  const handleDelete = async (channelId: string) => {
    if (confirm("Are you sure you want to delete this channel?")) {
      await adminApi.deleteChannel(channelId);
      refetch();
    }
  };

  const handleToggleActive = async (channelId: string, isActive: boolean) => {
    await adminApi.updateChannel(channelId, { is_active: !isActive });
    refetch();
  };

  const handleEdit = async (channelId: string) => {
    const channel = await adminApi.getChannel(channelId);
    setEditingChannel(channel);
    setEditForm({
      name: channel.name || "",
      description: channel.description || "",
      category: channel.category || "",
      image_url: channel.image_url || "",
      listen_url: channel.listen_url || "",
    });
  };

  const handleSaveEdit = () => {
    if (!editingChannel) return;
    updateMutation.mutate({
      channelId: editingChannel.channel_id,
      updates: {
        name: editForm.name || undefined,
        description: editForm.description || undefined,
        category: editForm.category || undefined,
        image_url: editForm.image_url || undefined,
        listen_url: editForm.listen_url || undefined,
      },
    });
  };

  const handleValidate = async (channelId: string) => {
    setValidatingChannelId(channelId);
    try {
      const response = await adminApi.startValidation(channelId);
      setValidationState(channelId, response.job_id);
    } catch {
      toast.error("Failed to start validation");
      setValidationState(null, null);
    }
  };

  const getStatusBadge = (status: ChannelStatus) => {
    switch (status) {
      case "active":
        return <Badge variant="default">Active</Badge>;
      case "draft":
        return <Badge variant="secondary">Draft</Badge>;
      case "inactive":
        return <Badge variant="outline">Inactive</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  // Render validation status indicator
  const renderValidationStatus = (channel: AdminChannelSummary) => {
    const { last_validation_status, last_validation_error, last_validated_at } = channel;

    // Format the date if available
    const dateStr = last_validated_at
      ? new Date(last_validated_at).toLocaleDateString()
      : "Never";

    if (!last_validation_status) {
      return <span className="text-muted-foreground">{dateStr}</span>;
    }

    switch (last_validation_status) {
      case "running":
      case "pending":
        return (
          <div className="flex items-center gap-1.5">
            <Loader2 className="h-3.5 w-3.5 animate-spin text-blue-500" />
            <span className="text-blue-600">Running...</span>
          </div>
        );
      case "completed":
        return (
          <div className="flex items-center gap-1.5">
            <CheckCircle2 className="h-3.5 w-3.5 text-green-500" />
            <span>{dateStr}</span>
          </div>
        );
      case "failed":
      case "timed_out":
        return (
          <div className="flex items-center gap-1.5 cursor-help" title={last_validation_error || "Unknown error"}>
            <XCircle className="h-3.5 w-3.5 text-red-500" />
            <span className="text-red-600">Failed</span>
          </div>
        );
      case "cancelled":
        return (
          <div className="flex items-center gap-1.5">
            <Clock className="h-3.5 w-3.5 text-gray-400" />
            <span className="text-muted-foreground">Cancelled</span>
          </div>
        );
      default:
        return <span className="text-muted-foreground">{dateStr}</span>;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">Channels</h2>
        <div className="flex gap-2">
          <select
            className="border rounded px-3 py-2 text-sm"
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
          >
            <option value="">All Types</option>
            <option value="youtube">YouTube</option>
            <option value="podcast">Podcast</option>
          </select>
          <select
            className="border rounded px-3 py-2 text-sm"
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value as ChannelStatus | "")}
          >
            <option value="">All Status</option>
            <option value="active">Active</option>
            <option value="draft">Draft</option>
            <option value="inactive">Inactive</option>
          </select>
          <Input
            placeholder="Search by name..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="max-w-xs"
          />
        </div>
      </div>

      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Name</TableHead>
                <TableHead>Type</TableHead>
                <TableHead>Episodes</TableHead>
                <TableHead>Transcribed</TableHead>
                <TableHead>Summarized</TableHead>
                <TableHead>Last Episode</TableHead>
                <TableHead>Last Validated</TableHead>
                <TableHead>Status</TableHead>
                <TableHead></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell
                    colSpan={9}
                    className="text-center py-8 text-muted-foreground"
                  >
                    Loading...
                  </TableCell>
                </TableRow>
              ) : data?.items.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={9}
                    className="text-center py-8 text-muted-foreground"
                  >
                    No channels found
                  </TableCell>
                </TableRow>
              ) : (
                data?.items.map((channel) => (
                  <Fragment key={channel.channel_id}>
                    <TableRow>
                      <TableCell className="font-medium">
                        <div>{channel.name}</div>
                        {channel.category && (
                          <div className="text-xs text-muted-foreground">
                            {channel.category}
                          </div>
                        )}
                      </TableCell>
                      <TableCell>
                        <Badge variant="outline">{channel.type}</Badge>
                      </TableCell>
                      <TableCell>{channel.episode_count}</TableCell>
                      <TableCell>
                        <span
                          className={
                            channel.transcribed_count > 0
                              ? "text-green-600"
                              : "text-muted-foreground"
                          }
                        >
                          {channel.transcribed_count}
                        </span>
                      </TableCell>
                      <TableCell>
                        <span
                          className={
                            channel.summarized_count > 0
                              ? "text-green-600"
                              : "text-muted-foreground"
                          }
                        >
                          {channel.summarized_count}
                        </span>
                      </TableCell>
                      <TableCell className="text-sm text-muted-foreground">
                        {channel.last_episode_at
                          ? new Date(channel.last_episode_at).toLocaleDateString()
                          : "-"}
                      </TableCell>
                      <TableCell className="text-sm">
                        {renderValidationStatus(channel)}
                      </TableCell>
                      <TableCell>{getStatusBadge(channel.status)}</TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleValidate(channel.channel_id)}
                            disabled={validatingChannelId === channel.channel_id}
                            title="Validate channel"
                          >
                            {validatingChannelId === channel.channel_id ? (
                              <Loader2 className="h-4 w-4 animate-spin" />
                            ) : (
                              <Play className="h-4 w-4" />
                            )}
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleEdit(channel.channel_id)}
                            title="Edit channel"
                          >
                            <Pencil className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() =>
                              handleToggleActive(channel.channel_id, channel.is_active)
                            }
                            title={channel.is_active ? "Deactivate" : "Activate"}
                          >
                            {channel.is_active ? (
                              <PowerOff className="h-4 w-4" />
                            ) : (
                              <Power className="h-4 w-4" />
                            )}
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleDelete(channel.channel_id)}
                            title="Delete channel"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                    {validatingChannelId === channel.channel_id && jobStatus && (
                      <TableRow>
                        <TableCell colSpan={9} className="bg-muted/50">
                          <ValidationProgress job={jobStatus} />
                        </TableCell>
                      </TableRow>
                    )}
                  </Fragment>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {data && data.pages > 1 && (
        <div className="flex justify-center gap-2">
          <Button
            variant="outline"
            disabled={page === 1}
            onClick={() => setPage((p) => p - 1)}
          >
            Previous
          </Button>
          <span className="py-2">
            Page {page} of {data.pages}
          </span>
          <Button
            variant="outline"
            disabled={page >= data.pages}
            onClick={() => setPage((p) => p + 1)}
          >
            Next
          </Button>
        </div>
      )}

      {/* Edit Channel Modal */}
      <Dialog open={!!editingChannel} onOpenChange={(open) => !open && setEditingChannel(null)}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>Edit Channel</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="name">Name</Label>
              <Input
                id="name"
                value={editForm.name}
                onChange={(e) => setEditForm((f) => ({ ...f, name: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="category">Category</Label>
              <Input
                id="category"
                value={editForm.category}
                onChange={(e) => setEditForm((f) => ({ ...f, category: e.target.value }))}
                placeholder="e.g., Technology, Science, Business"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={editForm.description}
                onChange={(e) => setEditForm((f) => ({ ...f, description: e.target.value }))}
                rows={3}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="image_url">Image URL</Label>
              <Input
                id="image_url"
                value={editForm.image_url}
                onChange={(e) => setEditForm((f) => ({ ...f, image_url: e.target.value }))}
                placeholder="https://..."
              />
              {editForm.image_url && (
                <img
                  src={editForm.image_url}
                  alt="Preview"
                  className="mt-2 h-16 w-16 rounded object-cover"
                  onError={(e) => (e.currentTarget.style.display = "none")}
                />
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="listen_url">Listen URL</Label>
              <Input
                id="listen_url"
                value={editForm.listen_url}
                onChange={(e) => setEditForm((f) => ({ ...f, listen_url: e.target.value }))}
                placeholder="https://open.spotify.com/... or https://podcasts.apple.com/..."
              />
            </div>

            {/* Read-only info */}
            {editingChannel && (
              <div className="pt-4 border-t text-sm text-muted-foreground space-y-1">
                <div>Type: {editingChannel.type}</div>
                {editingChannel.youtube_channel_id && (
                  <div>YouTube ID: {editingChannel.youtube_channel_id}</div>
                )}
                {editingChannel.youtube_playlist_id && (
                  <div>Playlist ID: {editingChannel.youtube_playlist_id}</div>
                )}
                {editingChannel.rss_feed_url && (
                  <div className="truncate">RSS: {editingChannel.rss_feed_url}</div>
                )}
              </div>
            )}
          </div>
          <div className="flex justify-end gap-2">
            <Button variant="outline" onClick={() => setEditingChannel(null)}>
              Cancel
            </Button>
            <Button onClick={handleSaveEdit} disabled={updateMutation.isPending}>
              {updateMutation.isPending ? "Saving..." : "Save Changes"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import * as React from "react"

