      className={cn(
        "text-foreground h-10 px-2 text-left align-middle font-medium whitespace-nowrap cursor-pointer select-none hover:bg-muted/50 transition-colors [&:has([role=checkbox])]:pr-0 [&>[role=checkbox]]:translate-y-[2px]",
