  };

  const getStatusBadge = (status: ChannelStatus) => {
    switch (status) {
      case "active":
        return <Badge variant="default">Active</Badge>;
      case "draft":
        return <Badge variant="secondary">Draft</Badge>;
      case "inactive":
        return <Badge variant="outline">Inactive</Badge>;
