import { useState, useCallback } from "react"

export type SortDirection = "asc" | "desc" | null

export interface SortConfig<T extends string = string> {
  column: T | null
  direction: SortDirection
}

// Helper hook for managing sort state
export function useSortState<T extends string>(
  defaultColumn: T | null = null,
  defaultDirection: SortDirection = null
) {
  const [sort, setSort] = useState<SortConfig<T>>({
    column: defaultColumn,
    direction: defaultDirection,
  })

  const handleSort = useCallback((column: T) => {
    setSort((prev) => {
      if (prev.column !== column) {
        return { column, direction: "asc" }
      }
      if (prev.direction === "asc") {
        return { column, direction: "desc" }
      }
      return { column: null, direction: null }
    })
  }, [])

  return [sort, handleSort] as const
}

// Helper function for sorting data
export function sortData<T>(
  data: T[],
  sort: SortConfig<string>,
  getters: Record<string, (item: T) => string | number | boolean | null | undefined>
): T[] {
  if (!sort.column || !sort.direction) return data

  const getter = getters[sort.column]
  if (!getter) return data

  return [...data].sort((a, b) => {
    const aVal = getter(a)
    const bVal = getter(b)

    // Handle nulls - push to end
    if (aVal == null && bVal == null) return 0
    if (aVal == null) return 1
    if (bVal == null) return -1

    // Compare based on type
    let comparison: number
    if (typeof aVal === "boolean" && typeof bVal === "boolean") {
      comparison = aVal === bVal ? 0 : aVal ? -1 : 1
    } else if (typeof aVal === "number" && typeof bVal === "number") {
      comparison = aVal - bVal
    } else {
      comparison = String(aVal).localeCompare(String(bVal))
    }

    return sort.direction === "asc" ? comparison : -comparison
  })
}

