import { useQuery } from "@tanstack/react-query";
import { useMemo, useState } from "react";
import { Trash2 } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  SortableTableHead,
} from "@/components/ui/table";
import { adminApi } from "@/lib/api";
import { useSortState, sortData } from "@/lib/sort";

type UserSortKey = "email" | "tier" | "is_admin" | "subscription_count" | "sent_delivery_count" | "created_at";

export function AdminUsers() {
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [sort, handleSort] = useSortState<UserSortKey>();

  const { data, isLoading, refetch } = useQuery({
    queryKey: ["admin-users", page, search],
    queryFn: () => adminApi.getUsers({ page, search: search || undefined }),
  });

  const items = data?.items ?? [];
  const sortedItems = useMemo(() => {
    return sortData(items, sort, {
      email: (u) => u.email,
      tier: (u) => u.tier,
      is_admin: (u) => u.is_admin,
      subscription_count: (u) => u.subscription_count,
      sent_delivery_count: (u) => u.sent_delivery_count,
      created_at: (u) => new Date(u.created_at).getTime(),
    });
  }, [items, sort]);

  const handleDelete = async (userId: string) => {
    if (confirm("Are you sure you want to delete this user?")) {
      await adminApi.deleteUser(userId);
      refetch();
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">Users</h2>
        <Input
          placeholder="Search by email..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="max-w-xs"
        />
      </div>

      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <SortableTableHead sortKey="email" currentSort={sort} onSort={handleSort}>Email</SortableTableHead>
                <SortableTableHead sortKey="tier" currentSort={sort} onSort={handleSort}>Tier</SortableTableHead>
                <SortableTableHead sortKey="is_admin" currentSort={sort} onSort={handleSort}>Admin</SortableTableHead>
                <SortableTableHead sortKey="subscription_count" currentSort={sort} onSort={handleSort}>Subscriptions</SortableTableHead>
                <SortableTableHead sortKey="sent_delivery_count" currentSort={sort} onSort={handleSort}>Sent</SortableTableHead>
                <SortableTableHead sortKey="created_at" currentSort={sort} onSort={handleSort}>Joined</SortableTableHead>
                <TableHead></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell
                    colSpan={7}
                    className="text-center py-8 text-muted-foreground"
                  >
                    Loading...
                  </TableCell>
                </TableRow>
              ) : sortedItems.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={7}
                    className="text-center py-8 text-muted-foreground"
                  >
                    No users found
                  </TableCell>
                </TableRow>
              ) : (
                sortedItems.map((user) => (
                  <TableRow key={user.user_id}>
                    <TableCell>{user.email}</TableCell>
                    <TableCell>
                      <Badge variant="secondary">{user.tier}</Badge>
                    </TableCell>
                    <TableCell>{user.is_admin && <Badge>Admin</Badge>}</TableCell>
                    <TableCell>{user.subscription_count}</TableCell>
                    <TableCell>{user.sent_delivery_count}</TableCell>
                    <TableCell>
                      {new Date(user.created_at).toLocaleDateString()}
                    </TableCell>
                    <TableCell>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleDelete(user.user_id)}
                        disabled={user.is_admin}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {data && data.pages > 1 && (
        <div className="flex justify-center gap-2">
          <Button
            variant="outline"
            disabled={page === 1}
            onClick={() => setPage((p) => p - 1)}
          >
            Previous
          </Button>
          <span className="py-2">
            Page {page} of {data.pages}
          </span>
          <Button
            variant="outline"
            disabled={page >= data.pages}
            onClick={() => setPage((p) => p + 1)}
          >
            Next
          </Button>
        </div>
      )}
    </div>
  );
}

