import { useQuery } from "@tanstack/react-query";
import { useMemo, useState } from "react";
import { RefreshCw, XCircle } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  SortableTableHead,
} from "@/components/ui/table";
import { adminApi } from "@/lib/api";
import { useSortState, sortData } from "@/lib/sort";

type DeliverySortKey = "episode_title" | "channel_name" | "user_email" | "status" | "attempts" | "last_error" | "created_at";

export function AdminDeliveries() {
  const [page, setPage] = useState(1);
  const [statusFilter, setStatusFilter] = useState("");
  const [sort, handleSort] = useSortState<DeliverySortKey>();

  const { data, isLoading, refetch } = useQuery({
    queryKey: ["admin-deliveries", page, statusFilter],
    queryFn: () =>
      adminApi.getDeliveries({
        page,
        status: statusFilter || undefined,
      }),
  });

  const items = data?.items ?? [];
  const sortedItems = useMemo(() => {
    return sortData(items, sort, {
      episode_title: (d) => d.episode_title || "",
      channel_name: (d) => d.channel_name,
      user_email: (d) => d.user_email,
      status: (d) => d.status,
      attempts: (d) => d.attempts,
      last_error: (d) => d.last_error || "",
      created_at: (d) => new Date(d.created_at).getTime(),
    });
  }, [items, sort]);

  const handleRetry = async (deliveryId: string) => {
    await adminApi.retryDelivery(deliveryId);
    refetch();
  };

  const handleCancel = async (deliveryId: string) => {
    if (confirm("Are you sure you want to cancel this delivery?")) {
      await adminApi.cancelDelivery(deliveryId);
      refetch();
    }
  };

  const getStatusVariant = (status: string) => {
    switch (status) {
      case "pending":
        return "secondary";
      case "processing":
        return "default";
      case "sent":
        return "default";
      case "failed":
        return "destructive";
      case "cancelled":
        return "outline";
      default:
        return "outline";
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">Deliveries</h2>
        <select
          className="border rounded px-3 py-2 text-sm"
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
        >
          <option value="">All Status</option>
          <option value="pending">Pending</option>
          <option value="processing">Processing</option>
          <option value="sent">Sent</option>
          <option value="failed">Failed</option>
          <option value="cancelled">Cancelled</option>
        </select>
      </div>

      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <SortableTableHead sortKey="episode_title" currentSort={sort} onSort={handleSort}>Episode</SortableTableHead>
                <SortableTableHead sortKey="channel_name" currentSort={sort} onSort={handleSort}>Channel</SortableTableHead>
                <SortableTableHead sortKey="user_email" currentSort={sort} onSort={handleSort}>User</SortableTableHead>
                <SortableTableHead sortKey="status" currentSort={sort} onSort={handleSort}>Status</SortableTableHead>
                <SortableTableHead sortKey="attempts" currentSort={sort} onSort={handleSort}>Attempts</SortableTableHead>
                <SortableTableHead sortKey="last_error" currentSort={sort} onSort={handleSort}>Error</SortableTableHead>
                <SortableTableHead sortKey="created_at" currentSort={sort} onSort={handleSort}>Created</SortableTableHead>
                <TableHead></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell
                    colSpan={8}
                    className="text-center py-8 text-muted-foreground"
                  >
                    Loading...
                  </TableCell>
                </TableRow>
              ) : sortedItems.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={8}
                    className="text-center py-8 text-muted-foreground"
                  >
                    No deliveries found
                  </TableCell>
                </TableRow>
              ) : (
                sortedItems.map((delivery) => (
                  <TableRow key={delivery.delivery_id}>
                    <TableCell className="max-w-xs truncate">
                      {delivery.episode_title || "Untitled"}
                    </TableCell>
                    <TableCell>{delivery.channel_name}</TableCell>
                    <TableCell>{delivery.user_email}</TableCell>
                    <TableCell>
                      <Badge variant={getStatusVariant(delivery.status)}>
                        {delivery.status}
                      </Badge>
                    </TableCell>
                    <TableCell>{delivery.attempts}</TableCell>
                    <TableCell className="max-w-xs truncate text-sm text-muted-foreground">
                      {delivery.last_error || "-"}
                    </TableCell>
                    <TableCell>
                      {new Date(delivery.created_at).toLocaleDateString()}
                    </TableCell>
                    <TableCell>
                      {delivery.status === "failed" && (
                        <div className="flex gap-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleRetry(delivery.delivery_id)}
                            title="Retry"
                          >
                            <RefreshCw className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleCancel(delivery.delivery_id)}
                            title="Cancel"
                          >
                            <XCircle className="h-4 w-4" />
                          </Button>
                        </div>
                      )}
                      {delivery.status === "pending" && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleCancel(delivery.delivery_id)}
                          title="Cancel"
                        >
                          <XCircle className="h-4 w-4" />
                        </Button>
                      )}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {data && data.pages > 1 && (
        <div className="flex justify-center gap-2">
          <Button
            variant="outline"
            disabled={page === 1}
            onClick={() => setPage((p) => p - 1)}
          >
            Previous
          </Button>
          <span className="py-2">
            Page {page} of {data.pages}
          </span>
          <Button
            variant="outline"
            disabled={page >= data.pages}
            onClick={() => setPage((p) => p + 1)}
          >
            Next
          </Button>
        </div>
      )}
    </div>
  );
}

